// And groups predicates with the AND operator between them.
func And(predicates ...predicate.QuantOrder) predicate.QuantOrder {
	return predicate.QuantOrder(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.QuantOrder) predicate.QuantOrder {
	return predicate.QuantOrder(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.QuantOrder) predicate.QuantOrder {
	return predicate.QuantOrder(sql.NotPredicates(p))
}
